def func_a(arr):
    ret = []
    for a in arr:
        a.sort()
        ret.append(a[1:-1])
    return ret

def func_b(arr):
    ret = []
    for a in arr:
        total = 0
        for b in a:
            total += b
        total = total // len(a)
        ret.append(total)
    ret.sort(reverse=True)
    return ret[0]

def solution(scores):
    arr = func_a(scores)
    answer = func_b(arr)
    return answer

